import time

from taf.internal.scpi import ScpiClient

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import VoltageNotInRange

from .base import PDU


class PSU(PDU):
    DEFAULT_PORT = 2268
    AVAILABLE_PORT = 1
    MIN_VOLTAGE = 35
    MAX_VOLTAGE = 61
    POWER_OFF = 0
    POWER_ON = 48

    def __init__(self, host, port=DEFAULT_PORT, timeout=10):
        super(PSU, self).__init__(host)
        self._timeout = timeout
        self.scpi_client = ScpiClient(ip=self._host, port=port)

    def get_voltage(self, port=None):
        value = float(
            self.scpi_client.execute_query(
                query="meas:volt:dc?", timeout=self._timeout
            )
        )
        return round(value, 2)

    def set_voltage(self, port, voltage):
        in_range = float(voltage) in range(PSU.MIN_VOLTAGE, PSU.MAX_VOLTAGE)
        if not in_range:
            raise VoltageNotInRange(
                f"Voltage {voltage} is not in the supported range <{PSU.MIN_VOLTAGE}, {PSU.MAX_VOLTAGE}>."
            )
        return self.scpi_client.execute_command(
            cmd=f"SOUR:VOLT:LEV:IMM:AMPL {str(voltage)}",
            timeout=self._timeout,
        )

    def power_on(self, port):
        """
        port: required to fit the signature but the value is ignored, i.e.,
        the operation is always performed on the AVAILABLE_PORT = 1
        """
        return super(PSU, self).power_on(port=PSU.AVAILABLE_PORT)

    def power_off(self, port):
        return super(PSU, self).power_off(port=PSU.AVAILABLE_PORT)

    def reset(self, ports, time_interval=5):
        return super(PSU, self).reset(
            ports=[PSU.AVAILABLE_PORT], time_interval=time_interval
        )

    def get_port_status(self, port):
        time.sleep(2)
        v = self.get_voltage()
        return DeviceStatus.OFF if v < PSU.MIN_VOLTAGE else DeviceStatus.ON

    def _set_port_status(self, port, status):
        """
        port: required to fit the signature but the value is ignored, i.e.,
        the operation is always performed on the AVAILABLE_PORT = 1
        """
        return self.scpi_client.execute_command(
            cmd=f"SOUR:VOLT:LEV:IMM:AMPL {self._port_setting()[status]}",
            timeout=self._timeout,
        )

    def _port_setting(self):
        return {
            DeviceStatus.OFF: PSU.POWER_OFF,
            DeviceStatus.ON: PSU.POWER_ON,
        }
